#include "ember/SfvSelectionAssetPath.hxx"

#include <algorithm>

namespace sfve::assets {

// Generated by CMakeLists.txt from data/pick-space.json (sfve_selection_assets).
extern const char* const kEmbeddedPickSpaceJson;

namespace {

std::wstring Wide(std::string_view text)
{
	return std::wstring(text.begin(), text.end());
}

// A decimal number as the builders write one: digits only, no sign, no
// leading zero (except 0 itself), at most six of them. `at` is left past it.
bool Number(std::wstring_view text, size_t& at, int& value)
{
	const size_t start = at;
	value = 0;
	while (at < text.size() && text[at] >= L'0' && text[at] <= L'9') {
		if (at - start >= 6) return false;
		value = value * 10 + (text[at] - L'0');
		at++;
	}
	if (at == start) return false;
	return !(text[start] == L'0' && at - start > 1);
}

bool Eat(std::wstring_view text, size_t& at, std::wstring_view literal)
{
	if (text.compare(at, literal.size(), literal) != 0) return false;
	at += literal.size();
	return true;
}

// `costume-<N>\color-<M>-cutout.png` over the fighter's costumes and colours.
bool IsCutout(std::wstring_view rest, const picks::Fighter& fighter)
{
	size_t at = 0;
	int costume = 0, colour = 0;
	if (!Eat(rest, at, L"costume-") || !Number(rest, at, costume)) return false;
	if (!Eat(rest, at, L"\\color-") || !Number(rest, at, colour)) return false;
	if (!Eat(rest, at, L"-cutout.png") || at != rest.size()) return false;
	for (const picks::Costume& entry : fighter.costumes) {
		if (entry.id == costume) return picks::HasColour(entry, colour);
	}
	return false;
}

// `vs<k>.png` and `vt<k>.png`, k from 1 to the fighter's number of choices.
bool IsLoadoutPicture(std::wstring_view rest, const picks::Fighter& fighter)
{
	if (rest.size() != 7 || rest[0] != L'v' || rest.substr(3) != L".png") return false;
	if (rest[1] != L's' && rest[1] != L't') return false;
	if (rest[2] < L'1' || rest[2] > L'9') return false;
	const picks::LoadoutPart part = rest[1] == L's' ? picks::LoadoutPart::VSkill : picks::LoadoutPart::VTrigger;
	return rest[2] - L'0' <= picks::PartChoices(fighter, part);
}

} // namespace

const picks::PickSpace& EmbeddedPickSpace()
{
	static const picks::PickSpace space = [] {
		picks::PickSpace parsed;
		std::string build, error;
		if (!picks::FromJson(kEmbeddedPickSpaceJson, parsed, build, error)) parsed = {};
		return parsed;
	}();
	return space;
}

bool IsSfvSelectionAssetPath(const std::wstring& path, const picks::PickSpace& space)
{
	const std::wstring_view root = kSelectionRoot;
	const std::wstring_view all = path;
	if (all.size() <= root.size() || all.compare(0, root.size(), root) != 0) return false;
	const std::wstring_view relative = all.substr(root.size());
	if (relative == L"manifest.json") return true;
	// <CODE>\...: the code as the pick space writes it, then one of the two
	// per-fighter forms. Every other character (a slash, a colon, a dot
	// segment) fails the exact comparisons below.
	const size_t divide = relative.find(L'\\');
	if (divide == std::wstring_view::npos) return false;
	const std::wstring_view code = relative.substr(0, divide);
	const std::wstring_view rest = relative.substr(divide + 1);
	for (const picks::Fighter& fighter : space.fighters) {
		if (code.size() != fighter.code.size() || !std::equal(code.begin(), code.end(), fighter.code.begin())) continue;
		return IsCutout(rest, fighter) || IsLoadoutPicture(rest, fighter);
	}
	return false;
}

bool IsSfvSelectionAssetPath(const std::wstring& path)
{
	return IsSfvSelectionAssetPath(path, EmbeddedPickSpace());
}

std::wstring ManifestPath()
{
	return std::wstring(kSelectionRoot) + L"manifest.json";
}

std::wstring CutoutPath(std::string_view fighterCode, int costume, int colour)
{
	if (fighterCode.empty() || costume < 0 || colour < 0) return {};
	return std::wstring(kSelectionRoot) + Wide(fighterCode) + L"\\costume-" + std::to_wstring(costume) + L"\\color-" +
		std::to_wstring(colour) + L"-cutout.png";
}

std::wstring LoadoutPicturePath(std::string_view fighterCode, picks::LoadoutPart part, int choice)
{
	if (fighterCode.empty() || choice < 0 || choice >= picks::kPartChoices) return {};
	return std::wstring(kSelectionRoot) + Wide(fighterCode) + (part == picks::LoadoutPart::VSkill ? L"\\vs" : L"\\vt") +
		std::to_wstring(choice + 1) + L".png";
}

} // namespace sfve::assets
